//! Bearer extraction for people and for runners.
//!
//! People are authenticated by a [`HumanAuth`] (in production
//! `metro_auth::Authenticator`), which yields a stable id for access control
//! and a display name.
//!
//! Runners hold one of two credentials, both generated by the server, shown
//! once, and stored only as SHA-256 hashes:
//!
//! - a *dedicated* (legacy) Space token, `metro_rt_<hex>`, issued by a Space
//!   owner and valid for that one Space;
//! - a *registered* runner token, `metro_rt_v2_<hex>`, belonging to a
//!   personal or organization runner that serves every Space it is attached
//!   to. It is accepted only with `X-Metro-Runner-Protocol: 2`, so an old
//!   single-workspace runner binary can never claim jobs of several Spaces.
//!
//! Managed local accounts (dev namespace only, see [`crate::admin_users`])
//! present `metro_ut_` tokens, which are looked up by hash in the database
//! before the configured authenticator is asked.
//!
//! Anything with the runner prefix, or the device connector prefix
//! (`metro_pc_`), is refused on human endpoints before the human
//! authenticator sees it; a human token never matches a runner hash. Runner
//! endpoints accept only `metro_rt_` tokens, so a device token is never a
//! runner credential either.

use std::future::Future;
use std::pin::Pin;
use std::time::Duration;

use axum::extract::FromRequestParts;
use axum::http::request::Parts;
use axum::http::{HeaderMap, header};
use sha2::{Digest, Sha256};

use crate::AppState;
use crate::admin_users::MANAGED_TOKEN_PREFIX;
use crate::api::ApiError;
use crate::db::Author;

/// Bounds a slow identity provider (such as a JWKS fetch).
const AUTH_TIMEOUT: Duration = Duration::from_secs(10);
/// Longest bearer token considered at all.
const MAX_TOKEN_LEN: usize = 16 * 1024;
/// Every runner token starts with this.
pub const RUNNER_TOKEN_PREFIX: &str = "metro_rt_";
/// Registered (reusable) runner tokens start with this. Dedicated tokens are
/// `metro_rt_` plus lowercase hex, so they can never start with it.
pub const REGISTERED_TOKEN_PREFIX: &str = "metro_rt_v2_";
/// Personal device connector tokens start with this. They are their own
/// bearer type: never accepted as a person's or a runner's credential.
pub const DEVICE_TOKEN_PREFIX: &str = "metro_pc_";
/// The header naming the runner wire protocol.
pub const PROTOCOL_HEADER: &str = "x-metro-runner-protocol";

/// Who a verified human bearer token belongs to.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UserIdentity {
    /// Stable id (dev username or OIDC `sub`). The only key for access control.
    pub id: String,
    /// Display name; may change and is never used for access control.
    pub actor: String,
}

/// Why a human bearer token was not accepted. The detail is for server logs
/// only and is never sent to clients.
#[derive(Debug)]
pub enum AuthFailure {
    /// Missing or invalid token: 401.
    Rejected(String),
    /// The identity provider could not be reached and cached keys are stale: 503.
    Unavailable(String),
}

pub type AuthFuture<'a> =
    Pin<Box<dyn Future<Output = Result<UserIdentity, AuthFailure>> + Send + 'a>>;

/// Resolves a human bearer token to an identity.
pub trait HumanAuth: Send + Sync + 'static {
    fn identity<'a>(&'a self, bearer: &'a str) -> AuthFuture<'a>;
    /// The namespace in which identity ids are unique (`dev`, `oidc:<issuer>`).
    fn namespace(&self) -> &str;
}

impl HumanAuth for metro_auth::Authenticator {
    fn identity<'a>(&'a self, bearer: &'a str) -> AuthFuture<'a> {
        Box::pin(async move {
            match metro_auth::Authenticator::identity(self, bearer).await {
                Ok(identity) => Ok(UserIdentity {
                    id: identity.id,
                    actor: identity.actor,
                }),
                Err(e) if e.is_unavailable() => Err(AuthFailure::Unavailable(e.to_string())),
                Err(e) => Err(AuthFailure::Rejected(e.to_string())),
            }
        })
    }

    fn namespace(&self) -> &str {
        metro_auth::Authenticator::namespace(self)
    }
}

/// The bearer token of a request, if it carries exactly one well-formed one.
fn bearer(headers: &HeaderMap) -> Option<&str> {
    let mut values = headers.get_all(header::AUTHORIZATION).iter();
    let value = values.next()?;
    if values.next().is_some() {
        return None;
    }
    let value = value.to_str().ok()?;
    let (scheme, token) = value.split_once(' ')?;
    if !scheme.eq_ignore_ascii_case("bearer") {
        return None;
    }
    let token = token.trim();
    if token.is_empty() || token.len() > MAX_TOKEN_LEN {
        return None;
    }
    Some(token)
}

/// A fresh dedicated Space runner token: the prefix and 256 random bits as hex.
pub fn new_runner_token() -> anyhow::Result<String> {
    token_with_prefix(RUNNER_TOKEN_PREFIX)
}

/// A fresh registered runner token.
pub fn new_registered_token() -> anyhow::Result<String> {
    token_with_prefix(REGISTERED_TOKEN_PREFIX)
}

fn token_with_prefix(prefix: &str) -> anyhow::Result<String> {
    let mut bytes = [0u8; 32];
    getrandom::fill(&mut bytes).map_err(|e| anyhow::anyhow!("no system randomness: {e}"))?;
    let mut token = String::with_capacity(prefix.len() + 64);
    token.push_str(prefix);
    for b in bytes {
        token.push_str(&format!("{b:02x}"));
    }
    Ok(token)
}

/// What the database stores for a runner token. The token has 256 bits of
/// entropy, so a plain SHA-256 needs no salt or stretching.
pub fn runner_token_hash(token: &str) -> Vec<u8> {
    Sha256::digest(token.as_bytes()).to_vec()
}

/// An authenticated person.
#[derive(Clone, Debug)]
pub struct Human {
    pub id: String,
    /// Display name for events.
    pub name: String,
}

impl Human {
    pub fn author(&self) -> Author {
        Author {
            id: Some(self.id.clone()),
            name: self.name.clone(),
        }
    }
}

impl FromRequestParts<AppState> for Human {
    type Rejection = ApiError;

    async fn from_request_parts(parts: &mut Parts, state: &AppState) -> Result<Self, ApiError> {
        let token = bearer(&parts.headers).ok_or_else(ApiError::unauthorized)?;
        if token.starts_with(RUNNER_TOKEN_PREFIX) {
            tracing::warn!("runner token presented on a human endpoint; refused");
            return Err(ApiError::unauthorized());
        }
        if token.starts_with(DEVICE_TOKEN_PREFIX) {
            tracing::warn!("device connector token presented on a human endpoint; refused");
            return Err(ApiError::unauthorized());
        }
        // Managed accounts exist only in the dev namespace; elsewhere their
        // tokens are never looked up.
        if state.managed.enabled()
            && token.starts_with(MANAGED_TOKEN_PREFIX)
            && let Some(human) = managed_human(state, token).await?
        {
            return with_profile(state, human).await;
        }
        // Otherwise (not, or no longer, a managed token) only the configured
        // authenticator can still accept it.
        match tokio::time::timeout(AUTH_TIMEOUT, state.auth.identity(token)).await {
            Ok(Ok(identity)) if valid_id(&identity.id) => {
                let human = Human {
                    name: display_name(&identity),
                    id: identity.id,
                };
                with_profile(state, human).await
            }
            Ok(Ok(_)) => {
                tracing::warn!("authenticator returned an unusable user id");
                Err(ApiError::unauthorized())
            }
            Ok(Err(AuthFailure::Rejected(reason))) => {
                tracing::debug!(%reason, "human authentication failed");
                Err(ApiError::unauthorized())
            }
            Ok(Err(AuthFailure::Unavailable(reason))) => {
                tracing::warn!(%reason, "identity provider unavailable");
                Err(ApiError::unavailable(
                    "authentication is temporarily unavailable",
                ))
            }
            Err(_) => {
                tracing::warn!("human authentication timed out");
                Err(ApiError::unavailable(
                    "authentication is temporarily unavailable",
                ))
            }
        }
    }
}

/// Show `human` under their profile name, if they set one. `human.name`
/// is what their authenticator calls them; it is recorded so people who
/// share a Space see a name even before an override. The result passes
/// [`display_name`] again, so no name can pose as the server's actors.
async fn with_profile(state: &AppState, human: Human) -> Result<Human, ApiError> {
    let (id, default) = (human.id.clone(), human.name.clone());
    let name = state
        .db
        .call(move |db| db.resolve_display_name(&id, &default))
        .await
        .map_err(ApiError::internal)?;
    Ok(Human {
        name: display_name(&UserIdentity {
            id: human.id.clone(),
            actor: name,
        }),
        id: human.id,
    })
}

/// The managed account `token` belongs to, read from the database on every
/// request so reissue and revoke take effect at once.
async fn managed_human(state: &AppState, token: &str) -> Result<Option<Human>, ApiError> {
    let hash = runner_token_hash(token);
    let found = state
        .db
        .call(move |db| db.managed_user_by_token_hash(&hash))
        .await
        .map_err(ApiError::internal)?;
    let Some((id, name)) = found else {
        return Ok(None);
    };
    if !crate::admin_users::is_managed_id(&id) || !valid_id(&id) {
        tracing::warn!("managed account with an unusable id; refused");
        return Err(ApiError::unauthorized());
    }
    // A name that has come to clash with an env user or admin (the
    // environment changed after it was chosen) shows the stable id instead.
    let clashes = state.managed.env_ids_contain(&name)
        || state
            .config
            .org_admins
            .iter()
            .any(|a| a.eq_ignore_ascii_case(&name));
    let actor = if clashes { id.clone() } else { name };
    Ok(Some(Human {
        name: display_name(&UserIdentity {
            id: id.clone(),
            actor,
        }),
        id,
    }))
}

/// User ids are what owners type to add members: printable, bounded.
pub fn valid_id(id: &str) -> bool {
    !id.trim().is_empty() && id == id.trim() && id.len() <= 256 && !id.chars().any(char::is_control)
}

/// The display name for events. A name that would impersonate the server's
/// own actors, or is unusable, falls back to the stable id, marked as a user.
fn display_name(identity: &UserIdentity) -> String {
    use crate::db::actor;
    let reserved = |n: &str| [actor::AGENT, actor::RUNNER, actor::SYSTEM].contains(&n.trim());
    let usable =
        |n: &str| !n.trim().is_empty() && n.len() <= 256 && !n.chars().any(char::is_control);
    if usable(&identity.actor) && !reserved(&identity.actor) {
        identity.actor.clone()
    } else if !reserved(&identity.id) {
        identity.id.clone()
    } else {
        format!("user:{}", identity.id)
    }
}

/// Which credential a runner presented.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RunnerCredential {
    /// A dedicated Space token; serves exactly one Space.
    Dedicated,
    /// A registered runner's token; serves the Spaces it is attached to.
    Registered { runner_id: String },
}

/// An authenticated runner: its credential, the Spaces it may serve right
/// now with each Space's runner generation (read from the database on this
/// request), and the wire protocol it speaks.
#[derive(Clone, Debug)]
pub struct Runner {
    pub credential: RunnerCredential,
    pub spaces: Vec<(String, u64)>,
    pub protocol: u8,
}

impl Runner {
    /// Who holds a claim in the job queue.
    pub fn claimer(&self) -> String {
        match &self.credential {
            RunnerCredential::Dedicated => "dedicated".to_owned(),
            RunnerCredential::Registered { runner_id } => format!("runner:{runner_id}"),
        }
    }
}

/// The protocol a runner request speaks: 1 without the header, `Some(2)`
/// with `2`, `None` for anything else.
fn protocol(headers: &HeaderMap) -> Option<u8> {
    let mut values = headers.get_all(PROTOCOL_HEADER).iter();
    let Some(value) = values.next() else {
        return Some(1);
    };
    if values.next().is_some() {
        return None;
    }
    match value.to_str().ok()?.trim() {
        "1" => Some(1),
        "2" => Some(2),
        _ => None,
    }
}

impl FromRequestParts<AppState> for Runner {
    type Rejection = ApiError;

    async fn from_request_parts(parts: &mut Parts, state: &AppState) -> Result<Self, ApiError> {
        let token = bearer(&parts.headers)
            .filter(|t| t.starts_with(RUNNER_TOKEN_PREFIX))
            .ok_or_else(ApiError::unauthorized)?;
        let registered = token.starts_with(REGISTERED_TOKEN_PREFIX);
        let hash = runner_token_hash(token);
        let found = state
            .db
            .call(move |db| {
                if registered {
                    Ok(db
                        .registered_runner_by_token_hash(&hash)?
                        .map(|(id, spaces)| {
                            (RunnerCredential::Registered { runner_id: id }, spaces)
                        }))
                } else {
                    Ok(db
                        .runner_by_token_hash(&hash)?
                        .map(|space| (RunnerCredential::Dedicated, vec![space])))
                }
            })
            .await
            .map_err(ApiError::internal)?;
        let Some((credential, spaces)) = found else {
            return Err(ApiError::unauthorized());
        };
        // Checked after the token, so an unknown token is always 401.
        let protocol = match (protocol(&parts.headers), &credential) {
            (Some(2), _) => 2,
            (Some(1), RunnerCredential::Dedicated) => 1,
            _ => {
                return Err(ApiError::new(
                    axum::http::StatusCode::UPGRADE_REQUIRED,
                    "this runner credential requires X-Metro-Runner-Protocol: 2; \
                     upgrade metro-runner",
                ));
            }
        };
        Ok(Runner {
            credential,
            spaces,
            protocol,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::http::HeaderValue;

    #[test]
    fn parses_bearer() {
        let mut h = HeaderMap::new();
        assert_eq!(bearer(&h), None);
        h.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer abc"),
        );
        assert_eq!(bearer(&h), Some("abc"));
        h.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("bearer  abc "),
        );
        assert_eq!(bearer(&h), Some("abc"));
        h.insert(header::AUTHORIZATION, HeaderValue::from_static("Basic abc"));
        assert_eq!(bearer(&h), None);
        h.insert(header::AUTHORIZATION, HeaderValue::from_static("Bearer "));
        assert_eq!(bearer(&h), None);
        h.insert(header::AUTHORIZATION, HeaderValue::from_static("Bearer a"));
        h.append(header::AUTHORIZATION, HeaderValue::from_static("Bearer b"));
        assert_eq!(bearer(&h), None);
    }

    #[test]
    fn display_names_cannot_impersonate_the_server() {
        let id = |id: &str, actor: &str| UserIdentity {
            id: id.into(),
            actor: actor.into(),
        };
        assert_eq!(display_name(&id("u1", "Alice")), "Alice");
        assert_eq!(display_name(&id("u1", "agent")), "u1");
        assert_eq!(display_name(&id("system", "runner")), "user:system");
        assert_eq!(display_name(&id("u1", "a\nb")), "u1");
    }

    #[test]
    fn runner_tokens_are_random_and_prefixed() {
        let a = new_runner_token().unwrap();
        let b = new_runner_token().unwrap();
        assert_ne!(a, b);
        assert!(a.starts_with(RUNNER_TOKEN_PREFIX));
        assert_eq!(a.len(), RUNNER_TOKEN_PREFIX.len() + 64);
        assert_eq!(runner_token_hash(&a).len(), 32);
        assert!(!a.starts_with(REGISTERED_TOKEN_PREFIX));
        let r = new_registered_token().unwrap();
        assert!(r.starts_with(REGISTERED_TOKEN_PREFIX));
        assert_eq!(r.len(), REGISTERED_TOKEN_PREFIX.len() + 64);
    }

    #[test]
    fn protocol_header() {
        let mut h = HeaderMap::new();
        assert_eq!(protocol(&h), Some(1));
        h.insert(PROTOCOL_HEADER, HeaderValue::from_static("2"));
        assert_eq!(protocol(&h), Some(2));
        h.insert(PROTOCOL_HEADER, HeaderValue::from_static("3"));
        assert_eq!(protocol(&h), None);
        h.insert(PROTOCOL_HEADER, HeaderValue::from_static("2"));
        h.append(PROTOCOL_HEADER, HeaderValue::from_static("2"));
        assert_eq!(protocol(&h), None);
    }
}
